-- Ensure Fresh Vegetables / Fresh Fruits exist, seed their 15 masters (skipped by V13 when missing),
-- and top up remaining thin categories to 15 items.

INSERT INTO categories (id, name, description)
SELECT v.id, v.name, v.description
FROM (VALUES
    ('c9a00000-0001-4000-8000-000000000001'::uuid, 'Fresh Vegetables', 'Onions, tomato, leafy greens and more'),
    ('c9a00000-0002-4000-8000-000000000002'::uuid, 'Fresh Fruits', 'Banana, apple, seasonal fruit')
) AS v(id, name, description)
WHERE NOT EXISTS (
    SELECT 1 FROM categories c WHERE c.id = v.id OR lower(btrim(c.name)) = lower(btrim(v.name))
);

